    "missing_info": { "type": "boolean", "description": "true if required information to answer the query is absent in retrieved chunks" },
    "retrieved_chunks": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "chunk_id": { "type": "string" },
          "document_id": { "type": "string" },
          "page_number": { "type": "integer" },
          "text": { "type": "string", "description": "excerpt or full chunk text" },
          "source_type": { "type": "string", "description": "e.g., raw_document, pdf, csv" }
        },
        "required": ["chunk_id", "text"]
      }
    },
    "actual_vs_expected": {
      "type": "object",
      "properties": {
        "expected_answer": { "type": "string" },
        "actual_answer": { "type": "string" },
        "evaluation": {
          "type": "object",
          "properties": {
            "hallucination": { "type": "boolean", "description": "true if generator produced unsupported facts" },
            "faithfulness": { "type": "string", "description": "qualitative faithfulness (e.g., high/medium/low)" },
            "answer_relevancy": { "type": "string", "description": "qualitative relevancy (e.g., exact/partial/irrelevant)" },
            "notes": { "type": "string" }
          }
        }
      },
      "required": ["expected_answer", "actual_answer"]
    },
    "retriever_metrics": {
      "type": "object",
      "properties": {
        "top_k_recall": { "type": "number" },
        "retriever_score": { "type": "number" },
        "failure_mode": { "type": "string", "description": "e.g., retriever, generator, none" }
