    "generator_metrics": {
      "type": "object",
      "properties": {
        "generator_score": { "type": "number" },
        "toxicity_flag": { "type": "boolean" },
        "summarization_quality": { "type": "string" }
      }
    }
  },
  "required": ["query", "chunk_count", "missing_info", "retrieved_chunks", "actual_vs_expected"]
}

